def compute(vars):
    total_without_fx = vars["v1"] - vars["v2"]
    return {
        "value": total_without_fx,
        "trace": {
            "total_net_of_all_collateral": vars["v1"],
            "foreign_exchange_derivative_receivables": vars["v2"],
            "total_without_foreign_exchange": total_without_fx,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
